refentry.refsect1:
&reftitle.errors;

 Throws a BadMethodCallException if the
 CachingIterator::FULL_CACHE flag is not set.

  &reftitle.examples;

   CachingIterator::count example


<?php
$iterator = new CachingIterator(
    new ArrayIterator(['a', 'b', 'c']),
    CachingIterator::FULL_CACHE
);

foreach ($iterator as $value) {
    echo $value, ': ', count($iterator), "\n";
}
?>


   &example.outputs;


a: 1
b: 2
c: 3
